create table public.myryra_health_exercise_entries (id uuid not null default gen_random_uuid(),user_id uuid not null,exercise_name text not null,muscle_group text not null,routine text not null,level text not null,weight_kg numeric(7,2),repetitions integer,performed_on date not null default CURRENT_DATE,created_at timestamp with time zone not null default now(),constraint myryra_health_exercise_entries_exercise_name_check CHECK (((char_length(exercise_name) >= 1) AND (char_length(exercise_name) <= 120))),constraint myryra_health_exercise_entries_level_check CHECK ((level = ANY (ARRAY['Iniciante'::text, 'Intermediário'::text, 'Avançado'::text]))),constraint myryra_health_exercise_entries_muscle_group_check CHECK ((muscle_group = ANY (ARRAY['Peito'::text, 'Costas'::text, 'Braços'::text, 'Ombros'::text, 'Pernas'::text, 'Abdômen'::text]))),constraint myryra_health_exercise_entries_pkey PRIMARY KEY (id),constraint myryra_health_exercise_entries_repetitions_check CHECK (((repetitions >= 0) AND (repetitions <= 100))),constraint myryra_health_exercise_entries_routine_check CHECK ((routine = ANY (ARRAY['Livre'::text, 'A'::text, 'B'::text, 'C'::text]))),constraint myryra_health_exercise_entries_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,constraint myryra_health_exercise_entries_weight_kg_check CHECK (((weight_kg >= (0)::numeric) AND (weight_kg <= (1000)::numeric)))); CREATE INDEX myryra_health_exercise_entries_owner_date ON public.myryra_health_exercise_entries USING btree (user_id, performed_on DESC); alter table public.myryra_health_exercise_entries enable row level security; revoke all on public.myryra_health_exercise_entries from public,anon,authenticated; grant INSERT,DELETE,SELECT on public.myryra_health_exercise_entries to authenticated; grant all on public.myryra_health_exercise_entries to service_role; create policy "owner add exercise entries" on public.myryra_health_exercise_entries for INSERT to authenticated with check ((( SELECT auth.uid() AS uid) = user_id));
