create table public.myryra_health_logs (id uuid not null default gen_random_uuid(),user_id uuid not null,category text not null,occurred_on date not null default CURRENT_DATE,value numeric(10,2),unit text,notes text not null default ''::text,created_at timestamp with time zone not null default now(),constraint health_log_unit CHECK (((unit IS NULL) OR (unit = ANY (ARRAY['kg'::text, 'minutes'::text, 'hours'::text, 'count'::text])))),constraint health_log_value CHECK (((value IS NULL) OR ((value >= (0)::numeric) AND (value <= (100000)::numeric)))),constraint myryra_health_logs_category_check CHECK ((category = ANY (ARRAY['weight'::text, 'workout'::text, 'meal'::text, 'sleep'::text, 'meditation'::text]))),constraint myryra_health_logs_notes_check CHECK ((char_length(notes) <= 500)),constraint myryra_health_logs_pkey PRIMARY KEY (id),constraint myryra_health_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE); CREATE INDEX myryra_health_logs_user_date ON public.myryra_health_logs USING btree (user_id, occurred_on DESC); alter table public.myryra_health_logs enable row level security; revoke all on public.myryra_health_logs from public,anon,authenticated; grant DELETE,INSERT,SELECT,UPDATE on public.myryra_health_logs to authenticated; grant all on public.myryra_health_logs to service_role; create policy "health_logs_delete_own" on public.myryra_health_logs for DELETE to authenticated using ((( SELECT auth.uid() AS uid) = user_id));
create policy "health_logs_insert_own" on public.myryra_health_logs for INSERT to authenticated with check ((( SELECT auth.uid() AS uid) = user_id));
create policy "health_logs_select_own" on public.myryra_health_logs for SELECT to authenticated using ((( SELECT auth.uid() AS uid) = user_id));
create policy "health_logs_update_own" on public.myryra_health_logs for UPDATE to authenticated using ((( SELECT auth.uid() AS uid) = user_id)) with check ((( SELECT auth.uid() AS uid) = user_id));
create table public.myryra_health_profiles (user_id uuid not null,goal text not null,activities text[] not null default '{}'::text[],days_per_week integer not null,minutes_per_session integer not null,limitations text not null default ''::text,updated_at timestamp with time zone not null default now(),constraint myryra_health_profiles_days_per_week_check CHECK (((days_per_week >= 1) AND (days_per_week <= 7))),constraint myryra_health_profiles_goal_check CHECK ((goal = ANY (ARRAY['lose'::text, 'maintain'::text, 'gain'::text, 'fitness'::text]))),constraint myryra_health_profiles_limitations_check CHECK ((char_length(limitations) <= 500)),constraint myryra_health_profiles_minutes_per_session_check CHECK (((minutes_per_session >= 10) AND (minutes_per_session <= 180))),constraint myryra_health_profiles_pkey PRIMARY KEY (user_id),constraint myryra_health_profiles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE);  alter table public.myryra_health_profiles enable row level security; revoke all on public.myryra_health_profiles from public,anon,authenticated; grant DELETE,INSERT,SELECT,UPDATE on public.myryra_health_profiles to authenticated; grant all on public.myryra_health_profiles to service_role; create policy "health_profile_delete_own" on public.myryra_health_profiles for DELETE to authenticated using ((( SELECT auth.uid() AS uid) = user_id));
