create policy "health_profile_select_own" on public.myryra_health_profiles for SELECT to authenticated using ((( SELECT auth.uid() AS uid) = user_id));
create policy "health_profile_update_own" on public.myryra_health_profiles for UPDATE to authenticated using ((( SELECT auth.uid() AS uid) = user_id)) with check ((( SELECT auth.uid() AS uid) = user_id));
